# -*- coding: utf-8 -*-
SVGS = ['<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VARLIĞIN MAHİYETİ (NE OLDUĞU) PROBLEMİ — KLASİK YAKLAŞIMLAR I</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#eff6ff" stroke="#2563eb" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#1e40af">1. VARLIĞI OLUŞ OLARAK GÖRENLER</text>\n  <text x="35" y="88" font-size="11.2" fill="#1e3a8a">• Temsilciler: Herakleitos ve A. N. Whitehead</text>\n  <text x="35" y="110" font-size="11.2" fill="#1e3a8a">• Temel Sav: Durağan bir varlık yoktur; her şey sürekli</text>\n  <text x="35" y="128" font-size="11.2" fill="#1e3a8a">  bir değişim, akış ve oluş (panta rhei) içindedir.</text>\n  <text x="35" y="150" font-size="11.2" fill="#1e3a8a">• «Aynı ırmakta iki kez yıkanılmaz.» (Herakleitos)</text>\n  <text x="35" y="172" font-size="11.2" fill="#1e3a8a">• Arkhe \'ateş\'tir; değişimin yasası ise \'Logos\'tur.</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#faf5ff" stroke="#9333ea" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#6b21a8">2. VARLIĞI İDEA (DÜŞÜNCE) OLARAK GÖRENLER</text>\n  <text x="370" y="88" font-size="11.2" fill="#581c87">• Yaklaşım: İdealizm (Platon, Aristoteles, Farabi, Hegel)</text>\n  <text x="370" y="110" font-size="11.2" fill="#581c87">• Platon: Gerçek varlık değişmeyen \'İdealar Evreni\'dir.</text>\n  <text x="370" y="130" font-size="11.2" fill="#581c87">• Aristoteles: Form (öz) maddenin içindedir (Dört Neden).</text>\n  <text x="370" y="150" font-size="11.2" fill="#581c87">• Farabi: Zorunlu Varlık (Vacibü\'l-Vücud) ve Mümkün Varlık</text>\n  <text x="370" y="170" font-size="11.2" fill="#581c87">• Hegel: Mutlak Ruh / Akıl (Geist) ve diyalektik süreç</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Ontolojide \'Varlık nedir?\' sorusu varlığın ana ilkesini (arkhe/töz) sorgular.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">VARLIĞIN MAHİYETİ PROBLEMİ — MATERYALİZM, DÜALİZM VE FENOMENOLOJİ</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fefce8" stroke="#ca8a04" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#854d0e">3. MATERYALİZM (MADDECİLİK)</text>\n  <text x="35" y="88" font-size="11.2" fill="#713f12">• Temsilciler: Demokritos, Hobbes, La Mettrie, Marx</text>\n  <text x="35" y="110" font-size="11.2" fill="#713f12">• Temel Sav: Varlığın ana tözü maddedir; düşünce ve</text>\n  <text x="35" y="128" font-size="11.2" fill="#713f12">  zihin maddenin bir ürünü ve yansımasıdır.</text>\n  <text x="35" y="150" font-size="11.2" fill="#713f12">• Mekanik Materyalizm: Evren ve insan makine gibidir.</text>\n  <text x="35" y="172" font-size="11.2" fill="#713f12">• Diyalektik Materyalizm (Marx): Maddenin çatışma yasası</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#f0fdf4" stroke="#16a34a" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#166534">4. DÜALİZM (İKİCİLİK) VE 5. FENOMENOLOJİ</text>\n  <text x="370" y="88" font-size="11.2" fill="#14532d">• Düalizm (Descartes): Varlık birbirine indirgenemeyen</text>\n  <text x="370" y="106" font-size="11.2" fill="#14532d">  iki tözden oluşur: Ruh (düşünen) ve Madde (yer kaplayan).</text>\n  <text x="370" y="130" font-size="11.2" fill="#14532d">• Fenomenoloji (Edmund Husserl): Varlık fenomen (görüngü)</text>\n  <text x="370" y="148" font-size="11.2" fill="#14532d">  olarak kavranır; bilincin nesnenin \'öz\'üne yönelmesi.</text>\n  <text x="370" y="170" font-size="11.2" font-weight="bold" fill="#166534">• Paranteze Alma (Epokhe): Ön yargıları askıya alma</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">İdealizm ve materyalizm tek töz (monizm) savunurken, Descartes\'ın düalizmi iki yaratılmış töz kabul eder.</text>\n</svg>', '<svg viewBox="0 0 700 260" xmlns="http://www.w3.org/2000/svg" font-family="Arial, sans-serif">\n  <rect width="700" height="260" fill="#f8fafc" rx="12"/>\n  <text x="350" y="26" text-anchor="middle" font-size="14.5" font-weight="bold" fill="#0f172a">ÇAĞDAŞ ONTOLOJİ (YENİ ONTOLOJİ) VE VAROLUŞÇULUK</text>\n  <rect x="22" y="42" width="320" height="175" rx="10" fill="#fff7ed" stroke="#ea580c" stroke-width="2"/>\n  <text x="182" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#9a3412">YENİ ONTOLOJİ (NICOLAI HARTMANN)</text>\n  <text x="35" y="86" font-size="11" fill="#7c2d12">• Varlığı tek bir ilkeye (madde veya ideaya) indirgemez;</text>\n  <text x="35" y="103" font-size="11" fill="#7c2d12">  deney ve bilimsel verilerle uyumlu \'katmanlar\' sunar:</text>\n  <text x="35" y="124" font-size="11" fill="#7c2d12">  1) İnorganik (Cansız) Katman → Fizik bilimi</text>\n  <text x="35" y="142" font-size="11" fill="#7c2d12">  2) Organik (Canlı) Katman → Biyoloji bilimi</text>\n  <text x="35" y="160" font-size="11" fill="#7c2d12">  3) Ruhsal (Bilinçli) Katman → Psikoloji bilimi</text>\n  <text x="35" y="178" font-size="11" fill="#7c2d12">  4) Tinsel (Kültür/Değer) Katmanı → Felsefe ve Tarih</text>\n  <rect x="358" y="42" width="320" height="175" rx="10" fill="#ecfeff" stroke="#0891b2" stroke-width="2"/>\n  <text x="518" y="64" text-anchor="middle" font-size="12.5" font-weight="bold" fill="#155e75">VAROLUŞÇULUK (EGZİSTANSİYALİZM)</text>\n  <text x="370" y="88" font-size="11.2" fill="#164e63">• Temsilciler: Kierkegaard, Nietzsche, Heidegger, Sartre</text>\n  <text x="370" y="110" font-size="11.2" fill="#164e63">• Temel Sav: «İnsanda varoluş özden önce gelir.» (Sartre)</text>\n  <text x="370" y="132" font-size="11.2" fill="#164e63">• Nesnelerin önce özü (tasarımı), sonra varoluşu vardır;</text>\n  <text x="370" y="150" font-size="11.2" fill="#164e63">  insan ise önce dünyaya gelir, özgür seçimleriyle</text>\n  <text x="370" y="168" font-size="11.2" fill="#164e63">  ve eylemleriyle kendi özünü (kimliğini) kendisi kurar.</text>\n  <rect x="22" y="224" width="656" height="26" rx="6" fill="#e2e8f0"/>\n  <text x="350" y="241" text-anchor="middle" font-size="11.5" font-weight="bold" fill="#1e293b">Hartmann\'da alt katmanlar daha güçlüdür, üst katmanlar ise alt katmanlara dayanmakla birlikte daha özgürdür.</text>\n</svg>']

def uygula(v):
    for i, b in enumerate(v.get("bolumler", [])):
        if i < len(SVGS):
            b["gorsel"] = SVGS[i]
